import assert from 'node:assert/strict';
import { PostHog } from 'posthog-node';
if (!process.env.VOLTER_WORLD) throw new Error('Run this app through its World.');
// Rallly with its PostHog analytics on (lukevella/rallly 3e63239d, apps/web/src/lib/posthog.ts), its keys the World
// issued: NEXT_PUBLIC_POSTHOG_API_KEY (the project token), POSTHOG_PERSONAL_API_KEY and POSTHOG_PROJECT_ID.
const env = { NEXT_PUBLIC_POSTHOG_API_KEY: process.env.NEXT_PUBLIC_POSTHOG_API_KEY, NEXT_PUBLIC_POSTHOG_API_HOST: process.env.NEXT_PUBLIC_POSTHOG_API_HOST };
assert.match(env.NEXT_PUBLIC_POSTHOG_API_KEY ?? '', /^phc_/);
const apiHost = process.env.POSTHOG_API_HOST ?? 'https://eu.posthog.com';
const headers = { Authorization: `Bearer ${process.env.POSTHOG_PERSONAL_API_KEY}` };
const api = (path) => fetch(`${apiHost}/api/projects/${process.env.POSTHOG_PROJECT_ID}${path}`, { headers, signal: AbortSignal.timeout(10_000) });

// Rallly's server client and helpers, unchanged but for their logger and types
let instance;
function posthog() {
  if (!instance && env.NEXT_PUBLIC_POSTHOG_API_KEY) {
    instance = new PostHog(env.NEXT_PUBLIC_POSTHOG_API_KEY, { host: env.NEXT_PUBLIC_POSTHOG_API_HOST, flushAt: 20, flushInterval: 10000 });
  }
  return instance;
}
function track(user, event) {
  posthog()?.capture({ ...event, distinctId: user.id, properties: { ...event.properties, $process_person_profile: !user.isGuest } });
}
async function flushPostHog() { await posthog()?.flush(); }
async function deletePostHogPerson({ distinctId }) {
  const lookupRes = await api(`/persons/?distinct_id=${encodeURIComponent(distinctId)}`);
  if (!lookupRes.ok) throw new Error(`PostHog person lookup failed: ${lookupRes.status}`);
  const { results } = await lookupRes.json();
  const person = results?.[0];
  if (!person) return;
  const deleteRes = await fetch(`${apiHost}/api/projects/${process.env.POSTHOG_PROJECT_ID}/persons/${person.id}/?delete_events=true`, { method: 'DELETE', headers, signal: AbortSignal.timeout(10_000) });
  if (!deleteRes.ok && deleteRes.status !== 404) throw new Error(`PostHog person deletion failed: ${deleteRes.status}`);
}
const eventsOf = async (distinctId) => (await (await api(`/events/?distinct_id=${encodeURIComponent(distinctId)}&after=2000-01-01T00:00:00Z`)).json()).results;
const personOf = async (distinctId) => (await (await api(`/persons/?distinct_id=${encodeURIComponent(distinctId)}`)).json()).results;

if (process.argv[2] === 'readback') {
  // after the World resumes: the kept person and events, read without writing
  const [person] = await personOf('user_ada');
  assert.deepEqual(person.distinct_ids, ['user_ada', 'guest_ada']);
  assert.equal(person.properties.email, 'ada@example.test');
  assert.deepEqual((await eventsOf('user_ada')).map((e) => e.event), ['poll_create', 'register']);
  console.log(JSON.stringify({ readback: person.uuid }));
} else {
  track({ id: 'guest_ada', isGuest: true }, { event: 'poll_comment_add', properties: { is_guest: true } });
  track({ id: 'user_ada', isGuest: false }, { event: 'register', properties: { method: 'email-otp', $set: { name: 'Ada', email: 'ada@example.test' } } });
  posthog()?.capture({ distinctId: 'user_ada', event: '$merge_dangerously', properties: { alias: 'guest_ada' } });
  track({ id: 'user_ada', isGuest: false }, { event: 'poll_create', properties: { optionCount: 3 } });
  await flushPostHog();
  const events = await eventsOf('user_ada');
  assert.deepEqual(events.map((e) => e.event).filter((e) => e !== '$merge_dangerously'), ['poll_create', 'register']);
  assert.equal(events.find((e) => e.event === 'poll_create').properties.optionCount, 3);
  const guest = await eventsOf('guest_ada');
  assert.equal(guest[0].properties.$process_person_profile, false);
  const [person] = await personOf('guest_ada');
  assert.deepEqual(person.distinct_ids, ['user_ada', 'guest_ada'], 'the guest is merged into Ada');
  assert.equal(person.properties.email, 'ada@example.test');
  // a second account is erased: its person goes at once, its events wait for the weekly run
  track({ id: 'user_bo', isGuest: false }, { event: 'register', properties: { $set: { email: 'bo@example.test' } } });
  await flushPostHog();
  await deletePostHogPerson({ distinctId: 'user_bo' });
  assert.deepEqual(await personOf('user_bo'), []);
  await posthog().shutdown();
  console.log(JSON.stringify({ person: person.uuid, events: events.length }));
}
